  presenceDetail: ["moving {0} cm (energy {1}) · stationary {2} cm (energy {3})", "en movimiento a {0} cm (energía {1}) · quieto a {2} cm (energía {3})", "bewegt {0} cm (Energie {1}) · ruhend {2} cm (Energie {3})", "en mouvement à {0} cm (énergie {1}) · immobile à {2} cm (énergie {3})", "in movimento a {0} cm (energia {1}) · fermo a {2} cm (energia {3})", "動き {0} cm（エネルギー {1}）· 静止 {2} cm（エネルギー {3}）", "运动 {0} 厘米（能量 {1}）· 静止 {2} 厘米（能量 {3}）"],
